// Package lru implements a fixed-capacity least-recently-used cache with
// O(1) expected-time operations.
package lru

// nilIndex marks the absence of a neighbour in the intrusive list.
const nilIndex = -1

type entry[K comparable, V any] struct {
	key        K
	value      V
	prev, next int32
}

// Cache is an LRU cache holding at most a fixed number of keys. Entries live
// in a slice and are linked by index, which keeps allocations low and lets
// freed slots be reused. The zero value is not usable; call New.
type Cache[K comparable, V any] struct {
	capacity int
	index    map[K]int32
	entries  []entry[K, V]
	free     []int32
	head     int32 // most recently used
	tail     int32 // least recently used
}

// New returns an empty cache that holds at most capacity keys. A capacity
// below one yields a cache that never retains anything.
func New[K comparable, V any](capacity int) *Cache[K, V] {
	hint := min(max(capacity, 0)+1, 1<<20)
	return &Cache[K, V]{
		capacity: capacity,
		index:    make(map[K]int32, hint),
		entries:  make([]entry[K, V], 0, hint),
		head:     nilIndex,
		tail:     nilIndex,
	}
}

// Len reports the number of keys currently held.
func (c *Cache[K, V]) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
func (c *Cache[K, V]) Get(key K) (V, bool) {
	i, ok := c.index[key]
	if !ok {
		var zero V
		return zero, false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set inserts or overwrites key, marks it most recently used, and evicts the
// least recently used key if the cache exceeds its capacity.
func (c *Cache[K, V]) Set(key K, value V) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}
	i := c.alloc(key, value)
	c.index[key] = i
	c.pushFront(i)
	if len(c.index) > c.capacity {
		c.remove(c.tail)
	}
}

// Delete removes key and reports whether it was present.
func (c *Cache[K, V]) Delete(key K) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache[K, V]) alloc(key K, value V) int32 {
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		c.entries[i] = entry[K, V]{key: key, value: value}
		return i
	}
	c.entries = append(c.entries, entry[K, V]{key: key, value: value})
	return int32(len(c.entries) - 1)
}

func (c *Cache[K, V]) remove(i int32) {
	c.unlink(i)
	delete(c.index, c.entries[i].key)
	c.entries[i] = entry[K, V]{} // release references for the GC
	c.free = append(c.free, i)
}

func (c *Cache[K, V]) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache[K, V]) pushFront(i int32) {
	e := &c.entries[i]
	e.prev = nilIndex
	e.next = c.head
	if c.head != nilIndex {
		c.entries[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache[K, V]) unlink(i int32) {
	e := &c.entries[i]
	if e.prev != nilIndex {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIndex {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev, e.next = nilIndex, nilIndex
}

package lru

import "testing"

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if got := c.Len(); got != 2 {
		t.Fatalf("Len() = %d; want 2", got)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q; want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New[string, int](3)
	for i := range 100 {
		c.Set("x", i)
		if !c.Delete("x") {
			t.Fatal("Delete(x) = false; want true")
		}
		if c.Delete("x") {
			t.Fatal("second Delete(x) = true; want false")
		}
	}
	if len(c.entries) != 1 {
		t.Fatalf("entries grew to %d; want 1", len(c.entries))
	}
}

func TestZeroCapacityHoldsNothing(t *testing.T) {
	c := New[string, string](0)
	c.Set("a", "1")
	if c.Len() != 0 {
		t.Fatalf("Len() = %d; want 0", c.Len())
	}
}

// Command app simulates an LRU cache. It reads a capacity followed by one
// command per line from standard input and writes results to standard output.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	err := run(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

// run processes the whole command stream from in, writing results to out.
func run(in io.Reader, out *bufio.Writer) error {
	lines := bufio.NewScanner(in)
	lines.Buffer(make([]byte, 0, 1<<16), 1<<30)
	lines.Split(scanLines)
	if !lines.Scan() {
		return lines.Err()
	}
	capacity, err := strconv.Atoi(string(trim(lines.Bytes())))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}
	cache := lru.New[string, string](capacity)
	for lines.Scan() {
		if line := trim(lines.Bytes()); len(line) > 0 {
			execute(cache, out, line)
		}
	}
	return lines.Err()
}

// execute runs a single non-empty command line. Unknown commands are ignored.
func execute(cache *lru.Cache[string, string], out *bufio.Writer, line []byte) {
	op, rest, hasArgs := bytes.Cut(line, []byte{' '})
	if !hasArgs {
		// A bare command takes the whole line as its argument.
		rest = line
	}
	switch string(op) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if !ok {
			return
		}
		cache.Set(string(key), string(value))
	case "GET":
		if v, ok := cache.Get(string(rest)); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if cache.Delete(string(rest)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
		out.WriteByte('\n')
	}
}

// trim removes leading and trailing ASCII control characters and spaces.
func trim(b []byte) []byte {
	start, end := 0, len(b)
	for start < end && b[start] <= ' ' {
		start++
	}
	for end > start && b[end-1] <= ' ' {
		end--
	}
	return b[start:end]
}

// scanLines is a bufio.SplitFunc that splits on "\n", "\r" or "\r\n",
// matching the line terminators accepted by the original implementation.
func scanLines(data []byte, atEOF bool) (advance int, token []byte, err error) {
	if i := bytes.IndexAny(data, "\r\n"); i >= 0 {
		if data[i] == '\n' {
			return i + 1, data[:i], nil
		}
		if i+1 < len(data) {
			if data[i+1] == '\n' {
				return i + 2, data[:i], nil
			}
			return i + 1, data[:i], nil
		}
		if atEOF {
			return i + 1, data[:i], nil
		}
		return 0, nil, nil // need one more byte to tell "\r" from "\r\n"
	}
	if atEOF && len(data) > 0 {
		return len(data), data, nil
	}
	return 0, nil, nil
}
